/// gh-2427 regression: the second DIRECT call to a tool the default
/// partition keeps out of the manifest must proceed natively after the
/// first call mounted it live.
///
/// The flake shape (issue #2427, RT1 "a second, shorter sheet fully
/// replaces the first"): two scripted `request_secret` calls in one run.
/// The tool is outside the keep-13 essential set (#2416), so the startup
/// availability apply unregisters it. The first direct call resolves
/// through the deferred-mount path (#2416 round 2) and mounts it — which
/// REMOVES it from the discoverable set — while the run's in-flight
/// context snapshot still misses it. The second direct call then died as
/// plain "Tool request_secret not found" on the round-2 resolver, the
/// second sheet never opened, and the residual test failed with no frame
/// on screen. The round-3 live-registry lookup in
/// `resolveDeferredToolForCall` (registry membership = mounted and
/// enabled) is the fix this test pins: both calls must reach the real
/// executor — two `[secret]` prompts, two grants, no not-found result —
/// exactly like the sheet flow over the PTY (see
/// `test/integration/secret_sheet_residual_test.dart` RT1).
library;

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

void main() {
  late MemoryExecutionEnv env;
  late FakeCliIO io;
  late FakeStreamFunction stream;

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work');
    io = FakeCliIO();
  });

  tearDown(() => io.close());

  ToolCall secretCall(String id, String name) => ToolCall(
    id: id,
    name: 'request_secret',
    arguments: {'name': name, 'reason': 'for the integration test'},
  );

  test(
    'a second direct call to a tool mounted earlier in the run executes',
    () async {
      stream = FakeStreamFunction([
        toolTurn([secretCall('tc-1', 'MY_SERVICE_TOKEN')]),
        toolTurn([secretCall('tc-2', 'OTHER_API_KEY')]),
        textTurn('settled'),
      ]);
      final cli = AgentCli(
        config: AgentCliConfig(
          model: testModel,
          apiKey: '[REDACTED:Sensitive-Value]',
          env: env,
          sessionRoot: '/sessions',
        ),
        io: io,
        streamFunction: stream.call,
      );
      final run = cli.run();
      // The startup availability apply must land BEFORE the run starts:
      // request_secret is outside the keep-13 essential set, so the
      // partition unregisters it — the precondition that makes both direct
      // calls below route through the deferred resolver.
      await io.out.waitUntilContains('fa>', reason: 'boot prompt');
      await waitForIt(
        () => !cli.agent.state.tools.any((t) => t.name == 'request_secret'),
        reason: 'request_secret demoted out of the manifest',
      );
      io.sendLine('need the key');

      // Call 1: the resolver mounts request_secret live; the host asks for
      // the value in line mode and the scripted grant lets the turn proceed.
      await io.out.waitUntilContains(
        '[secret] MY_SERVICE_TOKEN needed',
        reason: 'first request_secret prompt',
      );
      io.sendLine('token-1');

      // Call 2: the flake under test. The tool left the discoverable set
      // when call 1 mounted it, and this run's context snapshot still
      // misses it — the resolver must answer from the LIVE registry, not
      // the discoverable listing, or the call dies as plain not-found and
      // this second prompt never appears.
      await io.out.waitUntilContains(
        '[secret] OTHER_API_KEY needed',
        reason: 'second request_secret prompt (remount path)',
      );
      io.sendLine('token-2');

      await io.out.waitUntilContains('settled', reason: 'final text turn');
      expect(stream.calls, 3);
      final results = stream.contexts[2].messages
          .whereType<ToolResultMessage>();
      final second = results.last.content
          .whereType<TextContent>()
          .map((block) => block.text)
          .join();
      expect(
        second,
        contains('Secret OTHER_API_KEY is available as'),
        reason: 'the second direct call must execute natively after the mount',
      );
      expect(second, isNot(contains('not found')));

      io.sendLine('/exit');
      await run;
    },
  );
}

// Shared fakes and helpers for the agent_cli test suite.

// The scripted-stream half (test model, turn builders, fake stream) lives
// in the suite-neutral harness; re-exported so the suite's consumers keep
// this one import. The file's own remaining members (Abortable's abort
// turn) use it too.
export '../support/scripted_stream_harness.dart';
import '../support/scripted_stream_harness.dart';

import 'dart:async';
import 'dart:typed_data';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

/// A [StreamFunction] turn that hangs until cancelled, then reports aborted.
class AbortableStreamFunction {
  var started = false;

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    started = true;
    final stream = AssistantMessageEventStream();
    stream.push(StartEvent(partial: testAssistant()));
    cancelToken?.onCancel.then((_) {
      stream.push(
        ErrorEvent(
          reason: StopReason.aborted,
          error: testAssistant(
            stopReason: StopReason.aborted,
            errorMessage: 'Operation aborted',
          ),
        ),
      );
      stream.end();
    });
    return stream;
  }
}

/// A [Shell] that blocks until [release] completes the gate.
class GatedShell implements Shell {
  final _gate = Completer<void>();

  void release() => _gate.complete();

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
    String command, {
    ShellExecOptions? options,
  }) async {
    await _gate.future;
    return const Ok(ShellExecResult(stdout: '', stderr: '', exitCode: 0));
  }
}

/// A [Shell] that echoes the command and returns canned output.
class FakeShell implements Shell {
  FakeShell({this.stdout = '', this.stderr = '', this.exitCode = 0});

  final String stdout;
  final String stderr;
  final int exitCode;
  final commands = <String>[];
  ShellExecOptions? lastOptions;

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
    String command, {
    ShellExecOptions? options,
  }) async {
    commands.add(command);
    lastOptions = options;
    return Ok(
      ShellExecResult(stdout: stdout, stderr: stderr, exitCode: exitCode),
    );
  }
}

/// In-memory [CliIO]: scripted input lines, captured output.
/// Accumulating sink that also publishes every written chunk as a live
/// stream. Assertions read the buffer ([toString]/[contains]/[length]);
/// awaiters subscribe — [waitUntilContains] completes the moment the
/// accumulated output holds [needle], either immediately (sync buffer
/// check) or on the first chunk that completes it (stream wait, no
/// timers). Broadcast: late listeners see future chunks only, so arm the
/// wait BEFORE triggering the write when determinism matters.
class ListenableOutput implements StringSink {
  final _buf = StringBuffer();
  final _chunks = StreamController<void>.broadcast();

  /// Rings on every [write]/[writeln]: a wake-up bell, not a payload —
  /// awaiters re-check the accumulated buffer (see [waitUntilContains]).
  Stream<void> get chunks => _chunks.stream;

  bool contains(String needle) => _buf.toString().contains(needle);

  /// Bounded, timer-free wait for [needle] in the accumulated output.
  /// The sync check and the [StreamIterator] arm run in the same
  /// synchronous block, so a chunk cannot slip between them; the
  /// iterator's subscription is cancelled on EVERY exit path — match
  /// or timeout — so no stale waiter lingers on the broadcast stream.
  /// [seconds] caps the wait — expiry throws a named TimeoutException
  /// (loud, like waitForIt's fail).
  Future<void> waitUntilContains(
    String needle, {
    String? reason,
    int seconds = 25,
  }) async {
    // One event-loop turn BEFORE the buffer check. Seeing the needle in
    // the buffer must not shortcut the writer's own continuation: the
    // old 5ms polling closed exactly this gap — a line sent inside the
    // print→arm window (prompt printed, pending-answer not yet
    // registered) raced the pending-prompt routing and deadlocked on
    // `await _settled` in the input handler.
    await Future<void>.delayed(Duration.zero);
    if (contains(needle)) return;
    final chunks = StreamIterator<void>(_chunks.stream);
    try {
      while (!contains(needle)) {
        await chunks.moveNext().timeout(
          Duration(seconds: seconds),
          onTimeout: () {
            final tail = _buf.toString();
            final atTimeout = contains(needle);
            throw TimeoutException(
              'output missing: $needle'
              '${reason == null ? '' : ' — $reason'}'
              ' | contains() at timeout: $atTimeout\n'
              '--- buffer tail ---\n'
              '${tail.length > 600 ? tail.substring(tail.length - 600) : tail}',
            );
          },
        );
      }
    } finally {
      await chunks.cancel();
    }
  }

  void clear() => _buf.clear();

  int get length => _buf.length;

  bool get isEmpty => _buf.isEmpty;

  bool get isNotEmpty => _buf.isNotEmpty;

  void _emit(String s) {
    _buf.write(s);
    _chunks.add(null);
  }

  @override
  void write(Object? obj) => _emit('$obj');

  @override
  void writeln([Object? obj = '']) => _emit('$obj\n');

  @override
  void writeAll(Iterable objects, [String separator = '']) =>
      _emit(objects.join(separator));

  @override
  void writeCharCode(int charCode) => _emit(String.fromCharCode(charCode));

  @override
  String toString() => _buf.toString();
}

class FakeCliIO implements CliIO {
  @override
  int columns = 80;

  @override
  int rows = 24;

  final _lines = StreamController<String>();
  final _interrupts = StreamController<void>.broadcast();
  final _keys = StreamController<KeyEvent>.broadcast();
  final out = ListenableOutput();

  /// Tests flip this to exercise the non-interactive approval path.
  @override
  bool isInteractive = true;

  @override
  Stream<String> get lines => _lines.stream;

  @override
  Stream<void> get interrupts => _interrupts.stream;

  @override
  Stream<KeyEvent> get keys => _keys.stream;

  @override
  bool get supportsRawMode => true;

  @override
  void write(String text) => out.write(text);

  @override
  void writeln(String text) => out.writeln(text);

  void sendLine(String line) => _lines.add(line);

  void sendKey(KeyEvent key) => _keys.add(key);

  void interrupt() => _interrupts.add(null);

  Future<void> close() async {
    // The close future only completes once a listener received the done
    // event; tests that never ran the CLI have no listener, so don't await.
    unawaited(_lines.close());
    unawaited(_keys.close());
    await _interrupts.close();
  }
}

/// Split-channel headless IO — the canonical fixture for the headless
/// channel contract (gh-1292 review): [write] is the pipeable primary
/// stream (stdout — byte-identical assistant prose only, issue #774
/// AC3), [writeln] is the diagnostics channel (stderr on headless hosts,
/// per bin/fah_io.dart). Use it wherever a suite pins "this must reach
/// the captured run log but never pollute stdout" — sibling suites that
/// still hand-roll the shape (headless_cli, headless_hep,
/// markdown_surface, log_file_tee, ext_cli) adopt it incrementally.
class SplitChannelCliIO implements CliIO {
  final out = StringBuffer();
  final diag = StringBuffer();

  @override
  bool get isInteractive => false;

  @override
  int columns = 80;

  @override
  int rows = 24;

  @override
  Stream<String> get lines => const Stream<String>.empty();

  @override
  Stream<void> get interrupts => const Stream<void>.empty();

  @override
  Stream<KeyEvent> get keys => const Stream<KeyEvent>.empty();

  @override
  bool get supportsRawMode => false;

  @override
  void write(String text) => out.write(text);

  @override
  void writeln(String text) => diag.write('$text\n');
}

/// In-memory [SecureKeyStore] with a toggleable availability flag.
class FakeSecureKeyStore implements SecureKeyStore {
  FakeSecureKeyStore({this.available = true});

  bool available;
  bool failWrites = false;
  final map = <String, String>{};

  @override
  String get label => 'fake store';

  @override
  Future<bool> isAvailable() async => available;

  @override
  Future<String?> read(String name) async => map[name];

  @override
  Future<void> write(String name, String value) async {
    if (failWrites) throw StateError('keychain write failed (exit 45)');
    map[name] = value;
  }

  @override
  Future<void> delete(String name) async => map.remove(name);
}

/// The text carried by a transcript message or a fabric mail record —
/// the shared message-text extractor the routing/record-asserting suites
/// read contexts and mail entries with (hoisted from file-local copies,
/// gh-1947 review).
String messageText(Object message) {
  final content = switch (message) {
    UserMessage() => message.content,
    AssistantMessage() => message.content,
    ToolResultMessage() => message.content,
    AgentMessage() => message.text,
    _ => '',
  };
  return content is String
      ? content
      : content is List<ContentBlock>
      ? [
          for (final block in content)
            if (block is TextContent) block.text,
        ].join('\n')
      : '';
}

/// Polls [condition] until it holds or the [seconds] budget expires.
Future<void> waitForIt(
  FutureOr<bool> Function() condition, {
  String? reason,
  int seconds = 25,
}) async {
  // Generous budget: startup discovery + prompt composition must finish
  // within this window even on a LOADED machine (coverage instrumentation
  // roughly doubles run time; parallel builds/other projects' test runners
  // eat the rest). [seconds] of polling; the condition is checked every
  // 5ms so tests still finish as soon as the awaited state actually
  // appears. Async conditions are awaited (polling a Future beats a
  // silent fall-through on timeout — the failure must name the wait).
  for (var i = 0; i < seconds * 200; i++) {
    if (await condition()) return;
    await Future<void>.delayed(const Duration(milliseconds: 5));
  }
  fail('timed out waiting: ${reason ?? 'condition'}');
}

/// An env whose `.owner.json` renames fail for a chosen call window
/// (0-based, counting only sidecar publishes): the #2138 refused-claim
/// rig. Boot/switch renames on other paths (waiting manifest, usage
/// ledger) pass through untouched, so the window pins exactly which
/// lease claim refuses.
final class RenameGateEnv implements ExecutionEnv, RenamableFileSystem {
  RenameGateEnv(this._delegate, {required this.failFrom, required this.failTo});

  final MemoryExecutionEnv _delegate;

  /// The 0-based window of `.owner.json` rename calls that fail.
  final int failFrom;
  final int failTo;
  int _ownerRenames = 0;

  @override
  Future<Result<void, FileError>> renamePath(String from, String to) async {
    if (to.endsWith('.owner.json')) {
      final index = _ownerRenames++;
      if (index >= failFrom && index <= failTo) {
        return Err(
          FileError(FileErrorCode.unknown, 'injected owner rename failure'),
        );
      }
    }
    return _delegate.renamePath(from, to);
  }

  @override
  Future<Result<String, FileError>> readTextFile(String path) =>
      _delegate.readTextFile(path);

  @override
  String get cwd => _delegate.cwd;

  @override
  Future<Result<String, FileError>> absolutePath(String path) =>
      _delegate.absolutePath(path);

  @override
  Future<Result<String, FileError>> joinPath(List<String> parts) =>
      _delegate.joinPath(parts);

  @override
  Future<Result<Uint8List, FileError>> readBinaryFile(String path) =>
      _delegate.readBinaryFile(path);

  @override
  Future<Result<List<String>, FileError>> readTextLines(
    String path, {
    int? maxLines,
  }) => _delegate.readTextLines(path, maxLines: maxLines);

  @override
  Future<Result<void, FileError>> writeBinaryFile(
    String path,
    Uint8List content,
  ) => _delegate.writeBinaryFile(path, content);

  @override
  Future<Result<void, FileError>> writeFile(String path, String content) =>
      _delegate.writeFile(path, content);

  @override
  Future<Result<void, FileError>> appendFile(String path, String content) =>
      _delegate.appendFile(path, content);

  @override
  Future<Result<FileInfo, FileError>> fileInfo(String path) =>
      _delegate.fileInfo(path);

  @override
  Future<Result<List<FileInfo>, FileError>> listDir(String path) =>
      _delegate.listDir(path);

  @override
  Future<Result<bool, FileError>> exists(String path) => _delegate.exists(path);

  @override
  Future<Result<void, FileError>> createDir(
    String path, {
    bool recursive = true,
  }) => _delegate.createDir(path, recursive: recursive);

  @override
  Future<Result<void, FileError>> remove(
    String path, {
    bool recursive = false,
    bool force = false,
  }) => _delegate.remove(path, recursive: recursive, force: force);

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
    String command, {
    ShellExecOptions? options,
  }) => _delegate.exec(command, options: options);
}

/// GOAL #2394: whether [context] is the merged hand-over call — its LAST
/// user message is the rendered `prompts/compaction/hand_over.md`
/// instruction (the fold-range line), appended to the S0 prefix. The
